// Original citycmdd.c GetFood -> GREPORT131 STR_OBJ -> target Enter -> MSGBOX STR_ARMOUT.
function rebuildNativeMarchReportTail(a,{base=null,targetMutation=null,departureMutation=null}={}){
 const m=a.march,q=m.quantity;if(base)for(const x of[m.selection.initial,m.selection.beforeEnter,m.selection.fresh,m.partialTicket,q.initial,...q.steps.flatMap(s=>[s.before,s.fresh,s.after]),q.beforeEnter,q.fresh])Object.assign(x.state.snapshot.report,base);
 const tip=fixtureNativeMarchSnapshot(q.beforeEnter,92);if(targetMutation)targetMutation(tip);q.done.state.snapshot=copy(tip);
 for(const x of[m.targetWalk.initial,...m.targetWalk.steps.flatMap(s=>[s.before,s.fresh,s.after]),m.targetConfirmation.before,m.targetConfirmation.fresh])x.state.snapshot=copy(tip);
 const departure=fixtureNativeMarchSnapshot(m.targetConfirmation.before,93);if(departureMutation)departureMutation(departure);m.afterTicket.state.snapshot=copy(departure);
 const saved=saveTicket(m.afterTicket,m.publicSave.tag);m.publicSave=saved.publicSave;m.publicPair=saved.publicPair;m.publicKeys=saved.publicSaveKeys;
 for(const x of[a.endReady.before,a.endReady.first,a.endReady.second,a.endReady.final]){x.state.snapshot=copy(saved.publicSave.after.state.snapshot);x.world=copy(saved.publicSave.after.world);}return a;
}
test('Native March target-tip and departure reports bind original LIB text and U16 U32 nonzero wrap before ordinary SAVE',()=>{
 for(const [seq,inputSeq]of[[7,9],[65534,0xfffffffe],[65535,0xffffffff]]){
  const a=rebuildNativeMarchReportTail(createCity4Fixture(),{base:{seq,inputSeq}}),m=a.march,tip=m.quantity.done.state.snapshot.report,departure=m.afterTicket.state.snapshot.report,next=n=>((n+1)>>>0)||1,r=M.verifyCity4ConditionalEndAdmission(a);
  assert.deepEqual([tip.text,tip.person,tip.kind,tip.active],['选择目标',131,2,0]);assert.deepEqual([departure.text,departure.person,departure.kind,departure.active],['部队已出发',65535,1,0]);
  assert.equal(tip.seq,((seq+1)&65535)||1);assert.equal(tip.inputSeq,next(next(inputSeq)));assert.equal(departure.seq,((tip.seq+1)&65535)||1);assert.equal(departure.inputSeq,next(next(tip.inputSeq)));
  assert.equal(m.publicSave.after.state.snapshot.report.inputSeq,departure.inputSeq);assert.equal(m.publicSave.after.state.snapshot.report.person,65535);assert.deepEqual(tip.futureReport,m.quantity.beforeEnter.state.snapshot.report.futureReport);assert.equal(r.actualCurrentFoodSafe,false);noActual(r);
 }
});
